<script setup>
import {computed,nextTick,onUnmounted,ref,watch} from 'vue'
import UiIcon from './UiIcon.vue'
import MarkdownContent from './MarkdownContent.vue'
import {workbenchRequest,getCaseEvidence} from '../lib/backends'
import {formDraftKey,readFormDraft,writeFormDraft,clearFormDraft} from '../lib/formDrafts'
import '../styles/demo-project.css'
const props=defineProps({settings:Object,workspaceId:String,disabled:Boolean}),emit=defineEmits(['open'])
const project=ref(null),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('overview'),showAllEvents=ref(false),sourceFilter=ref('all')
const sourceDialog=ref(null),source=ref(null),sourceBusy=ref(false),sourceError=ref(''),fileUrl=ref('')
const approvalDialog=ref(null),selectedApproval=ref(null),approvalNote=ref(''),approvalPlan=ref(''),approvalBusy=ref(false),approvalError=ref(''),approvalConflict=ref(false),approvalBase=ref(1),approvalHash=ref('')
const scoped=computed(()=>({...props.settings,workspaceId:props.workspaceId})),api=(p,m='GET',b)=>workbenchRequest(scoped.value,p,m,b),userQuery=()=>new URLSearchParams({user_id:props.settings.userId})
const tabs=[{id:'overview',label:'项目'},{id:'progress',label:'进展'},{id:'todos',label:'待办'},{id:'approvals',label:'审批'},{id:'sources',label:'来源'}]
const statuses={in_progress:'进行中',completed:'已完成',pending:'待复核',approved:'已通过',returned:'已退回',open:'待处理',resolved:'内部已完成'}
const kindNames={customer:'客户原话',order:'订单记录',material:'材料清单',attachment:'原始凭证',policy:'演示规则',gap:'知识缺口',recheck:'回查记录',ticket:'工单跟进',approval:'方案复核',case:'事项处理'}
const approvalActionNames={submit:'提交申请',approve:'复核通过',return:'退回补充',resubmit:'补充后重新提交'}
const materialNames={missing:'待收集',received:'已收到，待核验',verified:'已核验',waived:'已豁免',withdrawn:'已撤回'}
const shownEvents=computed(()=>showAllEvents.value?project.value?.events:project.value?.events.slice(0,10))
const shownSources=computed(()=>project.value?.sources.filter(s=>sourceFilter.value==='all'||s.kind===sourceFilter.value)||[])
const time=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未安排'
const day=value=>value?new Date(value).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}):'—'
const tabKey=()=>formDraftKey(scoped.value,'project-tab',props.workspaceId),approvalKey=id=>formDraftKey(scoped.value,'project-approval',id)
let generation=0,sourceGeneration=0,restoringApproval=false
async function load(){const n=++generation;busy.value=true;error.value='';try{const data=await api('/demos/project?'+userQuery());if(n===generation)project.value=data}catch(e){if(n===generation)error.value=e.message}finally{if(n===generation)busy.value=false}}
watch(()=>[props.settings.userId,props.workspaceId,props.settings.backend],()=>{sourceGeneration++;source.value=null;sourceBusy.value=false;closeFile();project.value=null;tab.value=readFormDraft(tabKey())?.tab||'overview';if(!tabs.some(t=>t.id===tab.value))tab.value='overview';selectedApproval.value=null;approvalDialog.value?.close();sourceDialog.value?.close();load()},{immediate:true})
function changeTab(id){tab.value=id;writeFormDraft(tabKey(),{tab:id})}
async function tabKeys(event,id){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let index=tabs.findIndex(t=>t.id===id);index=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;changeTab(tabs[index].id);await nextTick();window.document.getElementById('project-tab-'+tabs[index].id)?.focus()}
function openCase(convId,step){emit('open',{workspaceId:props.workspaceId,convId,step})}
function openTodo(t){if(t.kind==='approval'){openApproval(project.value.approvals.find(a=>a.id===t.record_id));return}openCase(t.conv_id,{kind:t.kind==='recheck'?'customer':t.kind,id:t.record_id,conv_id:t.conv_id})}
function closeFile(){if(fileUrl.value)URL.revokeObjectURL(fileUrl.value);fileUrl.value=''}
async function openSource(id){const n=++sourceGeneration;source.value=null;sourceError.value='';sourceBusy.value=true;closeFile();await nextTick();if(!sourceDialog.value.open)sourceDialog.value.showModal();try{const data=await api('/demos/project/source?'+userQuery()+'&source_id='+encodeURIComponent(id));if(n!==sourceGeneration)return;source.value=data;if(data.kind==='attachment'){const blob=await getCaseEvidence(scoped.value,data.conv_id,data.data.id);if(n!==sourceGeneration)return;fileUrl.value=URL.createObjectURL(blob)}}catch(e){if(n===sourceGeneration)sourceError.value=e.message}finally{if(n===sourceGeneration)sourceBusy.value=false}}
function closeSource(){sourceGeneration++;sourceDialog.value.close();closeFile()}
onUnmounted(()=>{generation++;sourceGeneration++;closeFile()})
function openApproval(a){if(!a)return;restoringApproval=true;selectedApproval.value=a;approvalBase.value=a.revision;approvalHash.value=a.context_hash;approvalNote.value='';approvalPlan.value=a.plan;const saved=readFormDraft(approvalKey(a.id));if(saved){approvalNote.value=saved.note||'';approvalPlan.value=saved.plan||a.plan;approvalBase.value=saved.base;approvalHash.value=saved.hash}approvalConflict.value=!!saved&&(saved.base!==a.revision||saved.hash!==a.context_hash);approvalError.value='';restoringApproval=false;nextTick(()=>{if(!approvalDialog.value.open)approvalDialog.value.showModal()})}
watch([approvalNote,approvalPlan],()=>{if(restoringApproval||!selectedApproval.value)return;writeFormDraft(approvalKey(selectedApproval.value.id),{note:approvalNote.value,plan:approvalPlan.value,base:approvalBase.value,hash:approvalHash.value})},{flush:'sync'})
function rebaseApproval(){approvalBase.value=selectedApproval.value.revision;approvalHash.value=selectedApproval.value.context_hash;approvalConflict.value=false;writeFormDraft(approvalKey(selectedApproval.value.id),{note:approvalNote.value,plan:approvalPlan.value,base:approvalBase.value,hash:approvalHash.value})}
async function refreshApproval(){await load();const fresh=project.value?.approvals.find(a=>a.id===selectedApproval.value?.id);if(fresh)openApproval(fresh)}
async function decide(action){if(approvalBusy.value||!approvalNote.value.trim()||approvalConflict.value)return;const id=selectedApproval.value.id,key=approvalKey(id),actor=props.settings.userId,ws=props.workspaceId;approvalBusy.value=true;approvalError.value='';try{await api('/demos/project/approvals/'+id+'/decision','POST',{user_id:actor,action,note:approvalNote.value.trim(),...(action==='resubmit'?{plan:approvalPlan.value.trim()}:{}),expected_revision:approvalBase.value,expected_context_hash:approvalHash.value});clearFormDraft(key);if(actor!==props.settings.userId||ws!==props.workspaceId)return;approvalDialog.value.close();selectedApproval.value=null;await load();notice.value=action==='approve'?'方案复核已通过；材料核验和客户回访继续按原记录推进':action==='return'?'已记录退回原因，可以补充方案后重新提交':'补充方案已重新提交，历史记录保留'}catch(e){if(actor===props.settings.userId&&ws===props.workspaceId)approvalError.value=e.message}finally{approvalBusy.value=false}}
</script>
<template>
<section class="example-project" :aria-busy="busy" aria-label="完整项目示例">
 <p v-if="error" role="alert" class="form-error">{{error}} <button type="button" class="text-button" @click="load">重新读取项目</button></p><p v-if="busy&&!project" class="project-loading" role="status">正在准备项目、进展、待办、审批和来源…</p>
 <template v-if="project">
  <header class="project-intro"><div><span class="project-eyebrow">完整示例 / 售后服务</span><h2>{{project.title}}</h2><p>{{project.goal}}</p></div><span class="project-state">{{statuses[project.status]}}</span></header>
  <div class="project-meta"><span>{{project.owner_label}}</span><span>计划查看周期：{{day(project.created_at)}}—{{day(project.target_at)}}</span><span>合成示例 · 独立练习空间</span></div>
  <div class="project-metrics"><button type="button" @click="changeTab('progress')"><small>流程检查点</small><strong>{{project.completed}}<span> / {{project.total}}</span></strong></button><button type="button" @click="changeTab('todos')"><small>当前待办</small><strong>{{project.todos.length}}</strong></button><button type="button" @click="changeTab('approvals')"><small>待复核 / 待补充</small><strong>{{project.approval_pending}}</strong></button><button type="button" @click="changeTab('sources')"><small>可追溯来源</small><strong>{{project.sources.length}}</strong></button></div>
  <div class="project-tabs" role="tablist" aria-label="项目浏览"><button v-for="t in tabs" :id="'project-tab-'+t.id" :key="t.id" type="button" role="tab" :tabindex="tab===t.id?0:-1" @keydown="tabKeys($event,t.id)" :aria-selected="tab===t.id" :aria-controls="'project-panel-'+t.id" @click="changeTab(t.id)">{{t.label}}<small v-if="t.id==='todos'">{{project.todos.length}}</small><small v-if="t.id==='approvals'">{{project.approval_pending}} 待复核</small></button><button type="button" class="project-refresh" :disabled="busy||disabled" aria-label="刷新项目记录" @click="load"><UiIcon name="refresh" :size="16"/></button></div>
  <p v-if="notice" role="status" class="project-notice">{{notice}}</p>
  <div :id="'project-panel-'+tab" class="project-panel" role="tabpanel" :aria-labelledby="'project-tab-'+tab">
   <template v-if="tab==='overview'">
    <div class="project-overview-head"><div><h3>三条事项，一条完整业务主线</h3><p>先看每件事处理到哪，再进入待办、审批或原始记录。下面的进度会随实际练习记录更新。</p></div><button type="button" class="secondary" @click="changeTab('todos')">查看下一步待办</button></div>
    <div class="project-workstreams"><article v-for="c in project.cases" :key="c.id"><div class="project-stream-head"><span>{{c.generation}} 轮示例</span><strong>{{c.completed}} / {{c.total}}</strong></div><h4>{{c.title}}</h4><ol><li v-for="s in c.steps" :key="s.title" :class="{done:s.done}"><UiIcon :name="s.done?'check':'clock'" :size="14"/><span>{{s.title}}</span><small>{{s.done?'已完成':'待推进'}}</small></li></ol><button type="button" class="text-button" :disabled="disabled" @click="openCase(c.id)">打开原事项并继续对话 →</button></article></div>
    <div class="project-overview-bottom"><div><h4>审批与客户结果分开记录</h4><p>已有 {{project.approval_approved}} 项通过、{{project.approval_pending}} 项待复核或补充。方案通过后，仍需按材料核验和客户反馈继续处理。</p><button type="button" class="text-button" @click="changeTab('approvals')">浏览审批记录</button></div><div><h4>每条结论都能回到来源</h4><p>客户原话、合成订单、材料状态、演示凭证、规则版本和知识回查都已关联。</p><button type="button" class="text-button" @click="changeTab('sources')">核对原始依据</button></div></div>
   </template>
   <template v-else-if="tab==='progress'"><div class="project-section-head"><div><h3>已经发生了什么</h3><p>来自事项、工单、材料、客户结果和审批的记录；预置内容已标识。</p></div><button type="button" class="text-button" @click="showAllEvents=!showAllEvents">{{showAllEvents?'收起为最近 10 条':'展开全部 '+project.events.length+' 条'}}</button></div><ol class="project-timeline"><li v-for="(e,index) in shownEvents" :key="e.at+index"><time>{{time(e.at)}}</time><div><span class="project-kind">{{kindNames[e.kind]}}</span><small v-if="e.demo_seed">预置演示记录</small><h4>{{e.title}}</h4><p v-if="e.note">{{e.note}}</p><footer>{{e.actor}} <button type="button" class="text-button" :disabled="disabled" @click="openCase(e.conv_id)">打开关联事项</button></footer></div></li></ol></template>
   <template v-else-if="tab==='todos'"><div class="project-section-head"><div><h3>接下来由谁做什么</h3><p>待办读取当前记录；内部结案后的客户跟进也会保留。</p></div></div><div class="project-todos"><article v-for="t in project.todos" :key="t.id"><span class="project-kind">{{kindNames[t.kind]}}</span><div><h4>{{t.title}}</h4><p>{{t.case_label}} · {{t.owner}}</p><small>期限：{{time(t.due_at)}}</small></div><button type="button" class="secondary" :disabled="disabled" @click="openTodo(t)">{{t.kind==='approval'?'去复核':t.kind==='material'?'去核验':'去处理'}}</button></article><p v-if="!project.todos.length" class="source-note">当前项目没有未完成待办。可查看进展和历史来源。</p></div></template>
   <template v-else-if="tab==='approvals'"><div class="project-section-head"><div><h3>方案审批与复核</h3><p>这套示例同时包含待复核和已通过的计划，可查看意见、来源与处理历史。</p></div></div><div class="project-approvals"><article v-for="a in project.approvals" :key="a.id" :data-approval="a.status"><div><span class="project-approval-state" :class="a.status">{{statuses[a.status]}}</span><small>版本 {{a.revision}} · {{time(a.updated_at)}}</small></div><h4>{{a.title}}</h4><p>{{a.plan}}</p><small>{{a.submitted_by}} 提交 · {{a.approver_label}} 复核</small><p v-if="a.source_changed" class="project-source-warning">关联来源有后续更新，请按最新记录核对。</p><button type="button" class="secondary" :disabled="disabled" @click="openApproval(a)">{{a.status==='pending'?'查看来源并复核':a.status==='returned'?'补充方案并重提':'查看审批依据与历史'}}</button></article></div><details v-if="project.past_approvals.length" class="project-past"><summary>以前轮次的审批记录 · {{project.past_approvals.length}}</summary><p v-for="a in project.past_approvals" :key="a.id">{{a.title}} · {{statuses[a.status]}} <button type="button" class="text-button" @click="openApproval(a)">查看历史审批</button></p></details><p class="project-boundary">此处审批只确认合成示例中的本地处理计划，不执行真实补发、退款或通知，也不替代材料核验与客户确认。</p></template>
   <template v-else-if="tab==='sources'"><div class="project-section-head"><div><h3>从结论回到原始记录</h3><p>点击来源可直接核对内容、版本和历史；演示凭证可在这里预览。</p></div><label>来源类型<select v-model="sourceFilter" aria-label="筛选项目来源"><option value="all">全部来源</option><option v-for="k in ['customer','order','material','attachment','policy','gap','recheck']" :key="k" :value="k">{{kindNames[k]}}</option></select></label></div><div class="project-sources"><button v-for="s in shownSources" :key="s.id" type="button" class="project-source" :disabled="disabled" @click="openSource(s.id)"><span>{{kindNames[s.kind]}}<small v-if="s.version"> · v{{s.version}}</small></span><h4>{{s.title}}</h4><p>{{s.summary}}</p><small>{{s.case_label}} · 点击核对原记录</small></button></div></template>
  </div>
  <footer class="project-footer">进度按当前轮次的流程检查点计算。单案例新建一轮后，项目概览会关联新记录；以前的对话与审批保留。</footer>
 </template>
 <dialog ref="approvalDialog" class="project-dialog" aria-labelledby="project-approval-title"><div v-if="selectedApproval" :aria-busy="approvalBusy"><header><div><small>本地演示方案审批</small><h2 id="project-approval-title">{{selectedApproval.title}}</h2></div><button type="button" class="icon" aria-label="关闭方案审批" :disabled="approvalBusy" @click="approvalDialog.close()">×</button></header><p><span class="project-approval-state" :class="selectedApproval.status">{{statuses[selectedApproval.status]}}</span> · {{selectedApproval.approver_label}}</p><p v-if="approvalError" role="alert" class="form-error">{{approvalError}} <button type="button" class="text-button" @click="refreshApproval">刷新并保留我的说明</button></p><div v-if="approvalConflict" class="draft-conflict" role="alert"><p>方案或来源已有更新，未提交说明保留。核对最新记录后再操作。</p><button type="button" class="secondary" @click="rebaseApproval">已核对最新依据，保留说明继续</button></div><p class="project-plan" v-if="selectedApproval.status!=='returned'||selectedApproval.historical">{{selectedApproval.plan}}</p><label v-else>补充后的处理计划<textarea v-model.trim="approvalPlan" rows="4" maxlength="4000" :disabled="approvalBusy"/></label><h3>本次复核依据 · {{selectedApproval.current_sources.length}}</h3><p v-if="selectedApproval.source_changed" class="project-source-warning">来源有后续更新；本次审批将记录你核对时的来源快照。</p><div class="approval-source-links"><button v-for="s in selectedApproval.current_sources" :key="s.id" type="button" class="text-button" @click="openSource(s.id)">{{kindNames[s.kind]}} · {{s.title}}<small> {{s.summary.slice(0,90)}}</small></button></div><p v-if="selectedApproval.historical" class="project-boundary">此审批属于以前轮次，历史记录与来源摘要保留，只读查看。当前操作请回到本轮方案。</p><template v-if="selectedApproval.status!=='approved'&&!selectedApproval.historical"><label>复核意见 / 补充说明<textarea v-model.trim="approvalNote" rows="3" maxlength="2000" :disabled="approvalBusy" placeholder="写清通过、退回或重新提交的原因"/></label><p class="source-note">未提交说明会按当前成员和审批记录保留；此操作不会替代材料核验或客户确认。</p><div class="actions" v-if="selectedApproval.status==='pending'"><button type="button" class="primary" :disabled="approvalBusy||approvalConflict||!approvalNote.trim()" @click="decide('approve')">通过方案</button><button type="button" class="secondary" :disabled="approvalBusy||approvalConflict||!approvalNote.trim()" @click="decide('return')">退回补充</button></div><button v-else type="button" class="primary" :disabled="approvalBusy||approvalConflict||!approvalNote.trim()||!approvalPlan.trim()" @click="decide('resubmit')">补充后重新提交</button></template><details open class="project-approval-history"><summary>申请与审批历史 · {{selectedApproval.history.length}}</summary><article v-for="(h,i) in [...selectedApproval.history].reverse()" :key="i"><strong>{{approvalActionNames[h.action]}} · {{h.demo_seed?h.actor:'当前体验者'}}</strong><small>{{time(h.at)}} · {{h.demo_seed?'预置演示记录':'本次练习记录'}}</small><p>{{h.note}}</p><details><summary>当时的方案、来源版本与摘要</summary><p>{{h.plan}}</p><ul><li v-for="s in h.sources" :key="s.id">{{s.title}}<span v-if="s.version"> · v{{s.version}}</span> · {{s.summary}}</li></ul></details></article></details></div></dialog>
 <dialog ref="sourceDialog" class="project-dialog project-source-dialog" aria-labelledby="project-source-title"><div :aria-busy="sourceBusy"><header><div><small>合成示例 · 原始来源</small><h2 id="project-source-title">{{source?.title||'核对来源'}}</h2></div><button type="button" class="icon" aria-label="关闭来源详情" @click="closeSource">×</button></header><p v-if="sourceBusy" role="status">正在读取来源…</p><p v-if="sourceError" role="alert" class="form-error">{{sourceError}}</p><template v-if="source"><p class="source-note">{{kindNames[source.kind]}} · {{source.case_label}}<span v-if="source.data.version"> · v{{source.data.version}}</span></p><template v-if="source.kind==='customer'"><p class="project-source-quote">{{source.data.content}}</p><p class="source-note">预置的合成客户原话 · {{time(source.data.created_at)}}</p></template><template v-else-if="source.kind==='order'"><dl class="project-source-facts"><dt>合成订单号</dt><dd>{{source.data.display_id}}</dd><dt>状态</dt><dd>{{source.data.status==='delivered'?'已送达':source.data.status}}</dd><dt>预计送达</dt><dd>{{source.data.estimated_at}}</dd><dt>实际送达</dt><dd>{{source.data.delivered_at}}</dd><dt>商品与运费合计</dt><dd>{{source.data.total}} {{source.data.currency}}</dd></dl></template><template v-else-if="source.kind==='policy'"><MarkdownContent :markdown="source.data.content"/><h3>演示规则整理记录</h3><p v-for="(h,i) in source.data.review_history" :key="i">{{h.actor}} · {{h.action}} · {{h.note}}</p></template><template v-else-if="source.kind==='attachment'"><p>{{source.data.source_note}}</p><img v-if="fileUrl&&source.data.mime.startsWith('image/')" :src="fileUrl" :alt="source.data.filename"/><a v-if="fileUrl" :href="fileUrl" :download="source.data.filename">下载 {{source.data.filename}}</a></template><template v-else><p v-if="source.kind==='material'">{{materialNames[source.data.status]}} · {{source.data.required?'必要材料':'补充材料'}} · 期限 {{time(source.data.due_at)}}</p><p v-else-if="source.kind==='gap'">原始问题：{{source.data.original_question||source.data.question}}<br/>当前问题：{{source.data.question}}</p><p v-else>{{source.data.note}}</p><h3>原记录历史</h3><ol class="project-record-history"><li v-for="(h,i) in source.data.history||[]" :key="i"><strong>{{h.actor?.startsWith('示例')?h.actor:'当前体验者'}}</strong><time>{{time(h.at)}}</time><p>{{h.note||h.action}}</p></li></ol></template><button type="button" class="secondary" :disabled="disabled||approvalDialog?.open" @click="closeSource();openCase(source.conv_id)">打开来源所在事项</button></template></div></dialog>
</section>
</template>
